import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.Bogozrur.js";const h=JSON.parse('{"title":"Syntax Basics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/syntax.md","filePath":"guide/syntax.md"}'),i={name:"guide/syntax.md"};function o(p,a,l,d,c,r){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="syntax-basics" tabindex="-1">Syntax Basics <a class="header-anchor" href="#syntax-basics" aria-label="Permalink to &quot;Syntax Basics&quot;">​</a></h1><p>AAYU is designed to be as close to natural language as possible. It eliminates the need for curly braces <code>{}</code>, semicolons <code>;</code>, and complex syntax rules.</p><p>An AAYU block begins with a declaration (like <code>task</code>, <code>entity</code>, or <code>role</code>) and is explicitly closed using the <code>end.</code> keyword. Every statement in AAYU <strong>must end with a period <code>.</code></strong>, giving it the feel of an English sentence.</p><h2 id="tasks-and-printing" tabindex="-1">Tasks and Printing <a class="header-anchor" href="#tasks-and-printing" aria-label="Permalink to &quot;Tasks and Printing&quot;">​</a></h2><p>The <code>task</code> keyword is used to define functions or entry points. The main entry point of an AAYU application is <code>task main.</code>.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task main.</span></span>
<span class="line"><span>    print &quot;Hello AAYU&quot;.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><p>Variables in AAYU are strongly typed. You define them by declaring the type followed by the variable name.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text name.</span></span>
<span class="line"><span>number age.</span></span>
<span class="line"><span>boolean is_active.</span></span></code></pre></div><p>To assign a value, use the <code>set</code> keyword:</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set name to &quot;John Doe&quot;.</span></span>
<span class="line"><span>set age to 25.</span></span>
<span class="line"><span>set is_active to true.</span></span></code></pre></div><h2 id="conditionals" tabindex="-1">Conditionals <a class="header-anchor" href="#conditionals" aria-label="Permalink to &quot;Conditionals&quot;">​</a></h2><p>AAYU supports natural language if-else constructs.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if age &gt; 18.</span></span>
<span class="line"><span>    print &quot;Eligible&quot;.</span></span>
<span class="line"><span>else.</span></span>
<span class="line"><span>    print &quot;Not Eligible&quot;.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="maps-dictionaries" tabindex="-1">Maps (Dictionaries) <a class="header-anchor" href="#maps-dictionaries" aria-label="Permalink to &quot;Maps (Dictionaries)&quot;">​</a></h2><p>Maps allow you to store key-value pairs natively.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map user_data.</span></span>
<span class="line"><span>set user_data[&quot;name&quot;] to &quot;Alice&quot;.</span></span>
<span class="line"><span>set user_data[&quot;role&quot;] to &quot;Admin&quot;.</span></span></code></pre></div><h2 id="built-in-modules" tabindex="-1">Built-in Modules <a class="header-anchor" href="#built-in-modules" aria-label="Permalink to &quot;Built-in Modules&quot;">​</a></h2><p>AAYU comes with an extensive standard library. You can include them using the <code>use</code> keyword.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use http.</span></span>
<span class="line"><span>use db.</span></span>
<span class="line"><span>use auth.</span></span>
<span class="line"><span>use rbac.</span></span>
<span class="line"><span>use workflow.</span></span></code></pre></div><p>When you use AAYU for web development, the true power of the syntax shines. Head over to the <strong>Web Development</strong> section to see how entities, relations, and routes are declared.</p>`,21)])])}const b=s(i,[["render",o]]);export{h as __pageData,b as default};
